            basicDialogueJson = "[{\"speaker\": \"Math Teacher Mrs. White\", \"text\": \"Hello! Let us talk about talking about numbers.\", \"role\": \"A\"}, {\"speaker\": \"Student Henry\", \"text\": \"Hello! Yes, I want to talk about talking about numbers.\", \"role\": \"B\"}, {\"speaker\": \"Math Teacher Mrs. White\", \"text\": \"Do you practice talking about numbers often?\", \"role\": \"A\"}, {\"speaker\": \"Student Henry\", \"text\": \"Yes, I practice talking about numbers every day.\", \"role\": \"B\"}, {\"speaker\": \"Math Teacher Mrs. White\", \"text\": \"It is very simple to learn talking about numbers.\", \"role\": \"A\"}, {\"speaker\": \"Student Henry\", \"text\": \"I am happy to learn with you.\", \"role\": \"B\"}, {\"speaker\": \"Math Teacher Mrs. White\", \"text\": \"What is your favorite part of talking about numbers?\", \"role\": \"A\"}, {\"speaker\": \"Student Henry\", \"text\": \"My favorite part is practicing new words.\", \"role\": \"B\"}, {\"speaker\": \"Math Teacher Mrs. White\", \"text\": \"That sounds very nice!\", \"role\": \"A\"}, {\"speaker\": \"Student Henry\", \"text\": \"Thank you! I am trying my best.\", \"role\": \"B\"}, {\"speaker\": \"Math Teacher Mrs. White\", \"text\": \"Can you share one more detail about talking about numbers?\", \"role\": \"A\"}, {\"speaker\": \"Student Henry\", \"text\": \"Yes, talking about numbers helps me every day.\", \"role\": \"B\"}, {\"speaker\": \"Math Teacher Mrs. White\", \"text\": \"Great job! You speak very clearly.\", \"role\": \"A\"}, {\"speaker\": \"Student Henry\", \"text\": \"Thank you for helping me practice.\", \"role\": \"B\"}, {\"speaker\": \"Math Teacher Mrs. White\", \"text\": \"Let us practice talking about numbers again.\", \"role\": \"A\"}, {\"speaker\": \"Student Henry\", \"text\": \"Yes, I enjoy our practice time.\", \"role\": \"B\"}, {\"speaker\": \"Math Teacher Mrs. White\", \"text\": \"You are doing very well today.\", \"role\": \"A\"}, {\"speaker\": \"Student Henry\", \"text\": \"Thank you! I feel happy about my progress.\", \"role\": \"B\"}, {\"speaker\": \"Math Teacher Mrs. White\", \"text\": \"Thank you for practicing talking about numbers with me!\", \"role\": \"A\"}, {\"speaker\": \"Student Henry\", \"text\": \"Thank you! Have a great day!\", \"role\": \"B\"}]",
            intermediateDialogueJson = "[{\"speaker\": \"Math Teacher Mrs. White\", \"text\": \"Welcome! Today we are discussing intermediate phrases for talking about numbers.\", \"role\": \"A\"}, {\"speaker\": \"Student Henry\", \"text\": \"Hi! I'm eager to improve my conversational skills regarding talking about numbers.\", \"role\": \"B\"}, {\"speaker\": \"Math Teacher Mrs. White\", \"text\": \"How often do you encounter talking about numbers in your daily routine?\", \"role\": \"A\"}, {\"speaker\": \"Student Henry\", \"text\": \"I deal with talking about numbers quite often, especially during work or travel.\", \"role\": \"B\"}, {\"speaker\": \"Math Teacher Mrs. White\", \"text\": \"That's interesting! What challenges do you face with talking about numbers?\", \"role\": \"A\"}, {\"speaker\": \"Student Henry\", \"text\": \"Sometimes finding the exact words can be tricky, but I'm getting better.\", \"role\": \"B\"}, {\"speaker\": \"Math Teacher Mrs. White\", \"text\": \"Using natural expressions makes discussing talking about numbers much smoother.\", \"role\": \"A\"}, {\"speaker\": \"Student Henry\", \"text\": \"Yes! Idioms and phrasal verbs help me sound more natural and fluent.\", \"role\": \"B\"}, {\"speaker\": \"Math Teacher Mrs. White\", \"text\": \"Exactly! Notice how tone changes the meaning in this context.\", \"role\": \"A\"}, {\"speaker\": \"Student Henry\", \"text\": \"I agree, paying attention to intonation makes a huge difference.\", \"role\": \"B\"}, {\"speaker\": \"Math Teacher Mrs. White\", \"text\": \"Your explanation was very clear and well organized.\", \"role\": \"A\"}, {\"speaker\": \"Student Henry\", \"text\": \"Thank you! I've been trying to structure my thoughts before speaking.\", \"role\": \"B\"}, {\"speaker\": \"Math Teacher Mrs. White\", \"text\": \"How would you describe talking about numbers to a friend or colleague?\", \"role\": \"A\"}, {\"speaker\": \"Student Henry\", \"text\": \"I would keep it simple and highlight the main practical benefits.\", \"role\": \"B\"}, {\"speaker\": \"Math Teacher Mrs. White\", \"text\": \"That's a fantastic way to phrase it!\", \"role\": \"A\"}, {\"speaker\": \"Student Henry\", \"text\": \"Thanks! Hearing positive feedback builds my confidence.\", \"role\": \"B\"}, {\"speaker\": \"Math Teacher Mrs. White\", \"text\": \"We covered some key conversational phrases for talking about numbers today.\", \"role\": \"A\"}, {\"speaker\": \"Student Henry\", \"text\": \"Yes, I'm going to note down these key phrases right away.\", \"role\": \"B\"}, {\"speaker\": \"Math Teacher Mrs. White\", \"text\": \"Keep up the great work and practice these expressions regularly!\", \"role\": \"A\"}, {\"speaker\": \"Student Henry\", \"text\": \"Thank you so much! See you in our next practice session.\", \"role\": \"B\"}]",
            advancedDialogueJson = "[{\"speaker\": \"Math Teacher Mrs. White\", \"text\": \"Good day. Today we will analyze sophisticated nuances of talking about numbers.\", \"role\": \"A\"}, {\"speaker\": \"Student Henry\", \"text\": \"Good day. I welcome the opportunity to refine my discourse on talking about numbers.\", \"role\": \"B\"}, {\"speaker\": \"Math Teacher Mrs. White\", \"text\": \"How do you evaluate the strategic impact of talking about numbers in modern contexts?\", \"role\": \"A\"}, {\"speaker\": \"Student Henry\", \"text\": \"I view talking about numbers as a pivotal element driving systemic transformation.\", \"role\": \"B\"}, {\"speaker\": \"Math Teacher Mrs. White\", \"text\": \"Indeed. Nuanced diction allows for far greater rhetorical precision.\", \"role\": \"A\"}, {\"speaker\": \"Student Henry\", \"text\": \"Agreed. Choosing precise vocabulary enhances analytical clarity significantly.\", \"role\": \"B\"}, {\"speaker\": \"Math Teacher Mrs. White\", \"text\": \"Observe how stylistic devices elevate the overall delivery of talking about numbers.\", \"role\": \"A\"}, {\"speaker\": \"Student Henry\", \"text\": \"I appreciate how subtle vocal modulation reinforces key arguments.\", \"role\": \"B\"}, {\"speaker\": \"Math Teacher Mrs. White\", \"text\": \"Precisely. Synthesizing these concepts leads to compelling communication.\", \"role\": \"A\"}, {\"speaker\": \"Student Henry\", \"text\": \"I aim to integrate those advanced stylistic elements into my presentation.\", \"role\": \"B\"}, {\"speaker\": \"Math Teacher Mrs. White\", \"text\": \"Your articulate perspective reflects a high degree of linguistic mastery.\", \"role\": \"A\"}, {\"speaker\": \"Student Henry\", \"text\": \"Thank you. I strive for intellectual rigor and stylistic elegance.\", \"role\": \"B\"}, {\"speaker\": \"Math Teacher Mrs. White\", \"text\": \"How would you address potential counterarguments regarding talking about numbers?\", \"role\": \"A\"}, {\"speaker\": \"Student Henry\", \"text\": \"I would reframe the discussion around long-term strategic advantages.\", \"role\": \"B\"}, {\"speaker\": \"Math Teacher Mrs. White\", \"text\": \"An exceptionally reasoned and persuasive response!\", \"role\": \"A\"}, {\"speaker\": \"Student Henry\", \"text\": \"I appreciate your insightful critique of my argumentation.\", \"role\": \"B\"}, {\"speaker\": \"Math Teacher Mrs. White\", \"text\": \"We navigated complex analytical structures regarding talking about numbers today.\", \"role\": \"A\"}, {\"speaker\": \"Student Henry\", \"text\": \"Indeed, mastering these intricate nuances is vital for executive fluency.\", \"role\": \"B\"}, {\"speaker\": \"Math Teacher Mrs. White\", \"text\": \"Thank you for an intellectually stimulating discussion.\", \"role\": \"A\"}, {\"speaker\": \"Student Henry\", \"text\": \"Thank you for this masterclass! It was immensely valuable.\", \"role\": \"B\"}]",
