            intermediateDialogueJson = "[{\"speaker\": \"Partner Adam\", \"text\": \"Welcome! Today we are discussing intermediate phrases for romance and love.\", \"role\": \"A\"}, {\"speaker\": \"Partner Maya\", \"text\": \"Hi! I'm eager to improve my conversational skills regarding romance and love.\", \"role\": \"B\"}, {\"speaker\": \"Partner Adam\", \"text\": \"How often do you encounter romance and love in your daily routine?\", \"role\": \"A\"}, {\"speaker\": \"Partner Maya\", \"text\": \"I deal with romance and love quite often, especially during work or travel.\", \"role\": \"B\"}, {\"speaker\": \"Partner Adam\", \"text\": \"That's interesting! What challenges do you face with romance and love?\", \"role\": \"A\"}, {\"speaker\": \"Partner Maya\", \"text\": \"Sometimes finding the exact words can be tricky, but I'm getting better.\", \"role\": \"B\"}, {\"speaker\": \"Partner Adam\", \"text\": \"Using natural expressions makes discussing romance and love much smoother.\", \"role\": \"A\"}, {\"speaker\": \"Partner Maya\", \"text\": \"Yes! Idioms and phrasal verbs help me sound more natural and fluent.\", \"role\": \"B\"}, {\"speaker\": \"Partner Adam\", \"text\": \"Exactly! Notice how tone changes the meaning in this context.\", \"role\": \"A\"}, {\"speaker\": \"Partner Maya\", \"text\": \"I agree, paying attention to intonation makes a huge difference.\", \"role\": \"B\"}, {\"speaker\": \"Partner Adam\", \"text\": \"Your explanation was very clear and well organized.\", \"role\": \"A\"}, {\"speaker\": \"Partner Maya\", \"text\": \"Thank you! I've been trying to structure my thoughts before speaking.\", \"role\": \"B\"}, {\"speaker\": \"Partner Adam\", \"text\": \"How would you describe romance and love to a friend or colleague?\", \"role\": \"A\"}, {\"speaker\": \"Partner Maya\", \"text\": \"I would keep it simple and highlight the main practical benefits.\", \"role\": \"B\"}, {\"speaker\": \"Partner Adam\", \"text\": \"That's a fantastic way to phrase it!\", \"role\": \"A\"}, {\"speaker\": \"Partner Maya\", \"text\": \"Thanks! Hearing positive feedback builds my confidence.\", \"role\": \"B\"}, {\"speaker\": \"Partner Adam\", \"text\": \"We covered some key conversational phrases for romance and love today.\", \"role\": \"A\"}, {\"speaker\": \"Partner Maya\", \"text\": \"Yes, I'm going to note down these key phrases right away.\", \"role\": \"B\"}, {\"speaker\": \"Partner Adam\", \"text\": \"Keep up the great work and practice these expressions regularly!\", \"role\": \"A\"}, {\"speaker\": \"Partner Maya\", \"text\": \"Thank you so much! See you in our next practice session.\", \"role\": \"B\"}]",
            advancedDialogueJson = "[{\"speaker\": \"Partner Adam\", \"text\": \"Good day. Today we will analyze sophisticated nuances of romance and love.\", \"role\": \"A\"}, {\"speaker\": \"Partner Maya\", \"text\": \"Good day. I welcome the opportunity to refine my discourse on romance and love.\", \"role\": \"B\"}, {\"speaker\": \"Partner Adam\", \"text\": \"How do you evaluate the strategic impact of romance and love in modern contexts?\", \"role\": \"A\"}, {\"speaker\": \"Partner Maya\", \"text\": \"I view romance and love as a pivotal element driving systemic transformation.\", \"role\": \"B\"}, {\"speaker\": \"Partner Adam\", \"text\": \"Indeed. Nuanced diction allows for far greater rhetorical precision.\", \"role\": \"A\"}, {\"speaker\": \"Partner Maya\", \"text\": \"Agreed. Choosing precise vocabulary enhances analytical clarity significantly.\", \"role\": \"B\"}, {\"speaker\": \"Partner Adam\", \"text\": \"Observe how stylistic devices elevate the overall delivery of romance and love.\", \"role\": \"A\"}, {\"speaker\": \"Partner Maya\", \"text\": \"I appreciate how subtle vocal modulation reinforces key arguments.\", \"role\": \"B\"}, {\"speaker\": \"Partner Adam\", \"text\": \"Precisely. Synthesizing these concepts leads to compelling communication.\", \"role\": \"A\"}, {\"speaker\": \"Partner Maya\", \"text\": \"I aim to integrate those advanced stylistic elements into my presentation.\", \"role\": \"B\"}, {\"speaker\": \"Partner Adam\", \"text\": \"Your articulate perspective reflects a high degree of linguistic mastery.\", \"role\": \"A\"}, {\"speaker\": \"Partner Maya\", \"text\": \"Thank you. I strive for intellectual rigor and stylistic elegance.\", \"role\": \"B\"}, {\"speaker\": \"Partner Adam\", \"text\": \"How would you address potential counterarguments regarding romance and love?\", \"role\": \"A\"}, {\"speaker\": \"Partner Maya\", \"text\": \"I would reframe the discussion around long-term strategic advantages.\", \"role\": \"B\"}, {\"spea